SELECT jsonb_build_object('customer',(SELECT count(*) FROM app.customer_profiles WHERE id='bbe23c0b-ee0e-57f8-a60e-8333fe8650e2'),'command',(SELECT count(*) FROM platform.runtime_command_receipt WHERE id IN ('2d606abb-7830-5094-82f3-09e70adca015','b312887e-1745-5cc2-8e5e-36e08d06fbd1')), 'history',(SELECT count(*) FROM app.customer_profile_lifecycle_event WHERE customer_profile_id='bbe23c0b-ee0e-57f8-a60e-8333fe8650e2'),'evidence',(SELECT count(*) FROM platform.owner_mutation_evidence WHERE aggregate_kind='CustomerProfile' AND aggregate_id='bbe23c0b-ee0e-57f8-a60e-8333fe8650e2'),'outbox',(SELECT count(*) FROM platform.runtime_outbox_message WHERE command_receipt_id IN ('2d606abb-7830-5094-82f3-09e70adca015','b312887e-1745-5cc2-8e5e-36e08d06fbd1')),'track_enrollments',(SELECT count(*) FROM app.track_enrollment_receipt WHERE profile_id='bbe23c0b-ee0e-57f8-a60e-8333fe8650e2'),'coherent',EXISTS(SELECT 1 FROM app.customer_profiles c
