  AND q.result_body='{"contract":"SH-004.v1","requestId":"ctx01-source-customer","status":"ok","value":{"customerProfileId":"bbe23c0b-ee0e-57f8-a60e-8333fe8650e2","userId":"078052af-7e37-53e9-a1ae-462cceb06d30","lifecycle":"active","sourceToken":"0","receipt":{"owner":"customer_buyer_profile","id":"2d606abb-7830-5094-82f3-09e70adca015","semanticKey":"customer-controls-ctx01-source-customer","fingerprint":"5b80bc22fcd144a2d2b501f58f31c14b4046a9a5d58e033110594432dc74f193","sourceToken":"0","recordedAt":"2026-11-17T00:00:00Z"}}}'::jsonb AND q.result_digest=encode(sha256(convert_to(q.result_body::text,'UTF8')),'hex')
 JOIN app.customer_profile_lifecycle_event h ON h.id='0158773c-db88-52bc-b895-7dce8eef32e9' AND h.customer_profile_id=c.id AND h.command_receipt_id=q.id
  AND h.source_revision=0 AND h.from_status IS NULL AND h.to_status=c.status AND h.actor_user_id=c.user_id AND h.name='customer.lifecycle_changed.v1'
 JOIN platform.owner_mutation_evidence e ON e.id='7694bc87-8e5b-5b8b-bc9c-7bc8e039b18e' AND e.command_receipt_id=q.id AND e.owner_module_id=q.owner_module_id
  AND e.aggregate_kind='CustomerProfile' AND e.aggregate_id=c.id::text AND e.previous_revision IS NULL AND e.committed_revision=0
