  AND e.evidence_body='{"schema":"database-owner-evidence.v1","owner":"customer_buyer_profile","model":"CustomerProfile","primaryKey":{"id":"bbe23c0b-ee0e-57f8-a60e-8333fe8650e2"},"prior":null,"committed":{"id":"bbe23c0b-ee0e-57f8-a60e-8333fe8650e2","userId":"078052af-7e37-53e9-a1ae-462cceb06d30","status":"active","revision":"0","privacyGeneration":"0"},"decisionRef":"customer-controls-v1"}'::jsonb AND e.evidence_digest=encode(sha256(convert_to(e.evidence_body::text,'UTF8')),'hex')
 WHERE c.id='bbe23c0b-ee0e-57f8-a60e-8333fe8650e2' AND c.user_id='078052af-7e37-53e9-a1ae-462cceb06d30' AND c.status='active' AND c.revision=0 AND c.privacy_generation=0
