    AND o.payload_schema_id='urn:workin-ants:types:v1#/$defs/EventPayload_customer_lifecycle_changed_v1' AND o.payload='{"eventName":"customer.lifecycle_changed.v1","customerProfileId":"bbe23c0b-ee0e-57f8-a60e-8333fe8650e2","userId":"078052af-7e37-53e9-a1ae-462cceb06d30","lifecycleRevision":"0","safeState":"active"}'::jsonb)
